// Task sound effects — THIS FILE IS THE SOURCE OF TRUTH for the audio.
//
// Each clip is a mono MP3 embedded as a base64 `data:` URI so the Tasks module
// stays fully self-contained (no /public files, no network fetch). There are no
// separate .mp3 files — editing an .mp3 elsewhere would NOT change anything.
//
// To change a sound: base64-encode a new MP3 and replace that entry's string,
// keeping the `data:audio/mpeg;base64,` prefix. For example:
//   printf 'export …' ; base64 -i new-hover.mp3   # then paste over `hover:`
// (or: node -e 'console.log(require("fs").readFileSync("new.mp3","base64"))')

export type TaskSoundName =
  | "add"
  | "complete"
  | "uncomplete"
  | "delete"
  | "edit"
  | "tap"
  | "hover"
  | "tab"
  | "button"
  | "panel"

export const TASK_SOUND_DATA: Record<TaskSoundName, string> = {
  add: "data:audio/mpeg;base64,",
  complete: "data:audio/mpeg;base64,",
  uncomplete: "data:audio/mpeg;base64,",
  delete: "data:audio/mpeg;base64,",
  edit: "data:audio/mpeg;base64,",
  tap: "data:audio/mpeg;base64,",
  hover: "data:audio/mpeg;base64,",
  tab: "data:audio/mpeg;base64,",
  button: "data:audio/mpeg;base64,",
  panel: "data:audio/mpeg;base64,",
}
